def invoice(rental: dict[str, int]) -> dict[str, int]:
    slot = period(rental["start"], rental["duration"])
    base = usage_charge(slot, rental["base_rate"])
    extra = premium_charge(slot, rental["extra_rate"])
    return {"end_minute": slot.stop, "cents": base + extra}


def main(rentals: list[dict[str, int]]) -> list[dict[str, int]]:
    return [invoice(rental) for rental in rentals]
from typing import NamedTuple


class Span(NamedTuple):
    start: int
    stop: int


def period(start: int, duration: int) -> Span:
    return Span(start, start + duration)


def clip(left: Span, right: Span) -> Span:
    return Span(max(left.start, right.start), min(left.stop, right.stop))
from periods import Span, clip, period


def premium_charge(period_value: Span, rate: int) -> int:
    overlap = clip(period_value, period(540, 60))
    start, stop = overlap
    if stop < start:
        return 0
    return rate * (stop - start + 1)
from periods import Span


def usage_charge(period_value: Span, rate: int) -> int:
    start, stop = period_value
    if stop < start:
        return 0
    return rate * (stop - start + 1)
